INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106001, 1, 0, 1, 0, "2015/12/17 15:00:00", 7001, "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", "キャル", 0, 7, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105901, 1, 0, 1, 0, "2015/12/17 15:00:00", 7002, "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", "コッコロ", 0, 7, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105801, 1, 0, 1, 0, "2015/12/17 15:00:00", 7003, "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", "ペコリーヌ", 0, 7, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105801, 1, 0, 1, 0, "2015/12/17 15:00:00", 10001, "ジュエルを食べ物…\nいえ、貴重品と交換できます！", "ペコリーヌ", 0, 10, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106001, 1, 0, 1, 0, "2015/12/17 15:00:00", 10002, "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", "キャル", 0, 10, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105901, 1, 0, 1, 0, "2015/12/17 15:00:00", 10003, "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", "コッコロ", 0, 10, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106401, 1, 2104010, 2, 0, "2015/12/17 15:00:00", 10004, "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", "シェフィ", 0, 10, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105801, 1, 0, 1, 0, "2015/12/17 15:00:00", 12001, "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", "ペコリーヌ", 0, 12, -416.5);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106001, 1, 0, 1, 0, "2015/12/17 15:00:00", 13001, "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", "キャル", 0, 13, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105901, 1, 0, 1, 0, "2015/12/17 15:00:00", 13002, "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", "コッコロ", 0, 13, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106401, 1, 2104010, 2, 0, "2015/12/17 15:00:00", 13003, "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", "シェフィ", 0, 13, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105801, 1, 0, 1, 0, "2015/12/17 15:00:00", 13004, "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", "ペコリーヌ", 0, 13, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105901, 1, 0, 1, 0, "2015/12/17 15:00:00", 14001, "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", "コッコロ", 0, 14, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106401, 1, 2104010, 2, 0, "2015/12/17 15:00:00", 14002, "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", "シェフィ", 0, 14, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105801, 1, 0, 1, 0, "2015/12/17 15:00:00", 14003, "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", "ペコリーヌ", 0, 14, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106001, 1, 0, 1, 0, "2015/12/17 15:00:00", 14004, "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", "キャル", 0, 14, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105901, 1, 0, 1, 0, "2015/12/17 15:00:00", 15001, "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", "コッコロ", 0, 15, -470);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106401, 1, 2104010, 2, 0, "2015/12/17 15:00:00", 16001, "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", "シェフィ", 0, 16, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105801, 1, 0, 1, 0, "2015/12/17 15:00:00", 16002, "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", "ペコリーヌ", 0, 16, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106001, 1, 0, 1, 0, "2015/12/17 15:00:00", 16003, "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", "キャル", 0, 16, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105901, 1, 0, 1, 0, "2015/12/17 15:00:00", 16004, "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", "コッコロ", 0, 16, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105901, 1, 0, 1, 0, "2015/12/17 15:00:00", 17002, " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", "コッコロ", 0, 17, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106001, 1, 0, 1, 0, "2015/12/17 15:00:00", 17004, "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", "キャル", 0, 25, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105901, 1, 0, 1, 0, "2015/12/17 15:00:00", 17005, "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", "コッコロ", 0, 25, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106401, 1, 2104010, 2, 0, "2015/12/17 15:00:00", 17006, "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", "シェフィ", 0, 25, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105801, 1, 0, 1, 0, "2015/12/17 15:00:00", 17007, "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", "ペコリーヌ", 0, 25, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 1, 0, 1, 0, "2015/12/17 15:00:00", 18001, "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", "カリン", 0, 18, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 2, 0, 1, 0, "2015/12/17 15:00:00", 18002, "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", "カリン", 0, 18, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 3, 0, 1, 0, "2015/12/17 15:00:00", 19001, "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", "カリン", 0, 19, -470);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 4, 0, 1, 0, "2015/12/17 15:00:00", 19002, "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", "カリン", 0, 19, -470);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 5, 0, 1, 0, "2015/12/17 15:00:00", 20001, "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", "カリン", 0, 20, -470);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 6, 0, 1, 0, "2015/12/17 15:00:00", 20002, "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", "カリン", 0, 20, -470);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106001, 1, 0, 1, 0, "2015/12/17 15:00:00", 21001, "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", "キャル", 0, 21, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105901, 1, 0, 1, 0, "2015/12/17 15:00:00", 21002, "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", "コッコロ", 0, 21, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106401, 1, 2104010, 2, 0, "2015/12/17 15:00:00", 21003, "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", "シェフィ", 0, 21, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105801, 1, 0, 1, 0, "2015/12/17 15:00:00", 21004, "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", "ペコリーヌ", 0, 21, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 1, 0, 1, 0, "2015/12/17 15:00:00", 22001, "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", "カリン", 0, 22, -430);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 2, 0, 1, 0, "2015/12/17 15:00:00", 22002, "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", "カリン", 0, 22, -430);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 3, 0, 1, 0, "2015/12/17 15:00:00", 23001, "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", "カリン", 0, 23, -430);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 4, 0, 1, 0, "2015/12/17 15:00:00", 23002, "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", "カリン", 0, 23, -430);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (4.08, 2, "2030/12/17 14:59:59", 109001, 1, 0, 1, 10011, "2019/01/31 12:00:00", 24001, "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", "エリコ（バレンタイン）", 8, 24, -385);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (5, 2, "2030/12/17 14:59:59", 109001, 2, 0, 1, 10011, "2019/01/31 12:00:00", 24002, "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", "エリコ（バレンタイン）", 8, 24, -385);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (10.11, 2, "2030/12/17 14:59:59", 109001, 3, 0, 1, 10011, "2019/01/31 12:00:00", 24003, "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", "エリコ（バレンタイン）", 8, 24, -385);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (4, 2, "2030/12/17 14:59:59", 109001, 4, 0, 1, 10011, "2019/01/31 12:00:00", 24004, "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", "エリコ（バレンタイン）", 8, 24, -385);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (6, 2, "2030/12/17 14:59:59", 109001, 5, 0, 1, 10011, "2019/01/31 12:00:00", 24005, "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", "エリコ（バレンタイン）", 8, 24, -385);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 109002, 6, 0, 1, 10011, "2019/01/31 12:00:00", 24006, "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", "エリコ（バレンタイン）", 0, 24, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 109002, 7, 0, 1, 10011, "2019/01/31 12:00:00", 24007, "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", "エリコ（バレンタイン）", 0, 24, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 109002, 8, 0, 1, 10011, "2019/01/31 12:00:00", 24008, "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", "エリコ（バレンタイン）", 0, 24, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 109002, 9, 0, 1, 10011, "2019/01/31 12:00:00", 24009, "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", "エリコ（バレンタイン）", 0, 24, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 109002, 10, 0, 1, 10011, "2019/01/31 12:00:00", 24010, "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", "エリコ（バレンタイン）", 0, 24, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2.12, 2, "2030/12/17 14:59:59", 109101, 1, 0, 1, 10011, "2019/01/31 12:00:00", 24011, "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", "シズル（バレンタイン）", 8, 24, -385);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (4.19, 2, "2030/12/17 14:59:59", 109101, 2, 0, 5, 10011, "2019/01/31 12:00:00", 24012, "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", "シズル（バレンタイン）", 8, 24, -385);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2.3, 4, "2030/12/17 14:59:59", 109101, 3, 0, 2, 10011, "2019/01/31 12:00:00", 24013, "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", "シズル（バレンタイン）", 8, 24, -385);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 109102, 4, 0, 1, 10011, "2019/01/31 12:00:00", 24014, "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", "シズル（バレンタイン）", 0, 24, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (5.23, 2, "2030/12/17 14:59:59", 109101, 5, 0, 5, 10011, "2019/01/31 12:00:00", 24015, "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", "シズル（バレンタイン）", 8, 24, -385);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 109102, 6, 0, 1, 10011, "2019/01/31 12:00:00", 24016, "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", "シズル（バレンタイン）", 0, 24, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (5.01, 2, "2030/12/17 14:59:59", 109101, 7, 0, 1, 10011, "2019/01/31 12:00:00", 24017, "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", "シズル（バレンタイン）", 8, 24, -385);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 109102, 8, 0, 1, 10011, "2019/01/31 12:00:00", 24018, "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", "シズル（バレンタイン）", 0, 24, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 109102, 9, 0, 1, 10011, "2019/01/31 12:00:00", 24019, "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", "シズル（バレンタイン）", 0, 24, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 109102, 10, 0, 1, 10011, "2019/01/31 12:00:00", 24020, "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", "シズル（バレンタイン）", 0, 24, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106401, 1, 2104010, 2, 0, "2015/12/17 15:00:00", 26001, "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪", "シェフィ", 0, 26, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105801, 1, 0, 1, 0, "2015/12/17 15:00:00", 26002, "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！", "ペコリーヌ", 0, 26, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106001, 1, 0, 1, 0, "2015/12/17 15:00:00", 26003, "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ", "キャル", 0, 26, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105901, 1, 0, 1, 0, "2015/12/17 15:00:00", 26004, "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう", "コッコロ", 0, 26, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106401, 1, 2104010, 2, 0, "2015/12/17 15:00:00", 27001, "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか", "シェフィ", 0, 27, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105801, 1, 0, 1, 0, "2015/12/17 15:00:00", 27002, "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！", "ペコリーヌ", 0, 27, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106001, 1, 0, 1, 0, "2015/12/17 15:00:00", 27003, "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！", "キャル", 0, 27, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105901, 1, 0, 1, 0, "2015/12/17 15:00:00", 27004, "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。", "コッコロ", 0, 27, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 1, 0, 1, 0, "2019/09/24 15:00:00", 28001, "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！", "カリン", 0, 28, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 2, 0, 1, 0, "2019/09/24 15:00:00", 28002, "ギルド管理協会です\nフレンドに関しては\nこちらでご確認ください", "カリン", 0, 28, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 3, 0, 1, 0, "2019/09/24 15:00:00", 29001, "こちらがフレンドの\n皆さんです\n素敵な関係を\n築いてくださいね！", "カリン", 0, 29, -409);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 4, 0, 1, 0, "2019/09/24 15:00:00", 29002, "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ", "カリン", 0, 29, -409);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 5, 0, 1, 0, "2019/09/24 15:00:00", 30001, "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！", "カリン", 0, 30, -409);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 6, 0, 1, 0, "2019/09/24 15:00:00", 30002, "フレンドの申請や\n承認ができますよ\nどうぞ、良き交流を！", "カリン", 0, 30, -409);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 7, 0, 1, 0, "2019/10/31 12:00:00", 31001, "バトルをして力比べを\nしてみましょう！\n実力が試されますね、\n頑張ってください！", "カリン", 0, 31, -409);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 8, 0, 1, 0, "2019/10/31 12:00:00", 31002, "気になるパーティと\nバトルをしてみましょう！\nどちらが勝利するのか、\n私も楽しみにしていますね", "カリン", 0, 31, -409);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2020/01/04 4:59:59", 190801, 1, 0, 1, 0, "2019/12/20 5:00:00", 32001, "ルーキーの皆さんのために\n特別なミッションを\nご用意いたしました！\nぜひ、挑戦してください！", "カリン", 0, 32, -409);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2020/01/04 4:59:59", 190801, 2, 0, 1, 0, "2019/12/20 5:00:00", 32002, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", "カリン", 0, 32, -409);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2020/01/04 4:59:59", 190801, 3, 0, 1, 0, "2019/12/20 5:00:00", 33001, "フレンドになって\n初心者の方を応援しましょう！\n素敵な報酬が待っていますよ！", "カリン", 0, 33, -409);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2020/01/04 4:59:59", 190801, 4, 0, 1, 0, "2019/12/20 5:00:00", 33002, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", "カリン", 0, 33, -409);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2020/01/10 11:59:59", 190801, 5, 0, 1, 0, "2020/01/04 5:00:00", 34001, "お疲れ様でした！\nミッションの報酬の受け取りは\nこちらからできますよ！", "カリン", 0, 34, -409);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2020/01/10 11:59:59", 190801, 6, 0, 1, 0, "2020/01/04 5:00:00", 34002, "ミッション報酬の受け取りは\nこちら！\n受け取り漏れの無いように\n気を付けてくださいね！", "カリン", 0, 34, -409);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (5.3, 2, "2030/12/17 14:59:59", 105801, 1, 0, 1, 0, "2015/12/17 15:00:00", 38001, "過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪", "ペコリーヌ", 0, 38, -458);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (6.5, 2, "2030/12/17 14:59:59", 105801, 2, 0, 1, 0, "2015/12/17 15:00:00", 38002, "これまでのイベントで登場した\n限定キャラを仲間にできたり\nメモリーピースが手に入る\nみたいですよ。やばいですね☆", "ペコリーヌ", 0, 38, -458);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 3, "2020/04/08 23:59:59", 105801, 0, 0, 3, 0, "2020/04/01", 39005, "", "ペコリーヌ", 9999, 39, 9999);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 190801, 2, 0, 1, 0, "2015/12/17 15:00:00", 40001, "これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪", "カリン", 0, 40, -430);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106401, 1, 2104010, 1, 0, "2015/12/17 15:00:00", 41001, "ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。", "シェフィ", 0, 41, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105801, 1, 0, 1, 0, "2015/12/17 15:00:00", 41002, "ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！", "ペコリーヌ", 0, 41, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106001, 1, 0, 1, 0, "2015/12/17 15:00:00", 41003, "ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？", "キャル", 0, 41, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105901, 1, 0, 1, 0, "2015/12/17 15:00:00", 41004, "腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。", "コッコロ", 0, 41, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105901, 1, 0, 1, 0, "2015/12/17 15:00:00", 42001, "訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。", "コッコロ", 0, 42, -416.5);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106401, 1, 2104010, 1, 0, "2015/12/17 15:00:00", 42002, "目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。", "シェフィ", 0, 42, -416.5);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105801, 1, 0, 1, 0, "2015/12/17 15:00:00", 42003, "腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆", "ペコリーヌ", 0, 42, -416.5);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106001, 1, 0, 1, 0, "2015/12/17 15:00:00", 42004, "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！", "キャル", 0, 42, -416.5);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105801, 1, 0, 1, 0, "2015/12/17 15:00:00", 43001, "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", "ペコリーヌ", 0, 43, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 105901, 1, 0, 1, 0, "2015/12/17 15:00:00", 43002, "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。", "コッコロ", 0, 43, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 106001, 1, 0, 1, 0, "2015/12/17 15:00:00", 43003, "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", "キャル", 0, 43, -363);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 123001, 1, 0, 1, 0, "2015/12/17 15:00:00", 43004, "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", "アメス", 0, 44, -416.5);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 123001, 2, 0, 1, 0, "2015/12/17 15:00:00", 43005, "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", "アメス", 0, 44, -416.5);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (5.79, 2, "2030/12/17 14:59:59", 123001, 3, 0, 1, 0, "2015/12/17 15:00:00", 43006, "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", "アメス", 0, 45, -416.5);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 1, "2030/12/17 14:59:59", 123001, 1, 0, 1, 0, "2015/12/17 15:00:00", 46001, "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", "アメス", 0, 46, -371.5);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 2, "2030/12/17 14:59:59", 104901, 1, 0, 2, 0, "2015/12/17 15:00:00", 47001, "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", "シズル", 0, 47, -416.5);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (9.32, 2, "2030/12/17 14:59:59", 101101, 1, 0, 1, 0, "2015/12/17 15:00:00", 47002, "ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪", "リノ", 0, 47, -416.5);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 2, "2030/12/17 14:59:59", 104901, 0, 0, 2, 0, "2015/12/17 15:00:00", 48001, "", "シズル", 0, 48, -470);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 2, "2030/12/17 14:59:59", 101101, 0, 0, 2, 0, "2015/12/17 15:00:00", 48002, "", "リノ", 0, 48, -470);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 2, "2030/12/17 14:59:59", 134901, 0, 0, 1, 0, "2015/12/17 15:00:00", 49001, "", "カノン", -15, 49, -290);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 2, "2030/12/17 14:59:59", 190801, 0, 0, 1, 0, "2015/12/17 15:00:00", 50001, "", "カリン", -15, 50, -450);
